   157	
   158	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
   159	        int nights = 0;
   160	        BigDecimal subtotal = cents(BigDecimal.ZERO);
   161	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
   162	            subtotal = subtotal.add(nightPrice(room, night));
   163	            nights++;
   164	        }
   165	        BigDecimal discount = switch (ratePlan) {
   166	            case STANDARD -> cents(BigDecimal.ZERO);
   167	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
   168	        };
   169	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
   170	    }
